//! The config leaves of the script, generated by `build.rs` from its `config` and `help_text`.

use super::json::Value;

/// One leaf of the script's `config` dict, which is one command-line option.
#[derive(Debug)]
pub struct Leaf {
    /// Keys from the root of the config.
    pub path: &'static [&'static str],
    /// The long option without its leading `--`.
    pub option: &'static str,
    pub default: DefaultValue,
    pub help: &'static str,
}

#[derive(Debug)]
pub enum DefaultValue {
    Value(Literal),
    /// `Optional(type)`: left out of the config unless given.
    Optional(OptionalKind),
}

/// The `type` of an `Optional` leaf.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum OptionalKind {
    Int,
    Str,
    Float,
    Bool,
    List,
}

/// A Python literal of the script.
#[derive(Debug)]
pub enum Literal {
    Null,
    Bool(bool),
    /// Normalized decimal digits, as Python ints have no size limit.
    Int(&'static str),
    Float(f64),
    Str(&'static str),
    List(&'static [Literal]),
    /// `ipc_endpoint(path, port)`.
    Endpoint {
        ipc: &'static str,
        port: &'static str,
    },
}

impl Literal {
    pub(crate) fn to_value(&self) -> Value {
        match self {
            Self::Null => Value::Null,
            Self::Bool(flag) => Value::Bool(*flag),
            Self::Int(digits) => Value::Int((*digits).to_owned()),
            Self::Float(float) => Value::Float(*float),
            Self::Str(text) => Value::Str((*text).to_owned()),
            Self::List(items) => Value::List(items.iter().map(Self::to_value).collect()),
            Self::Endpoint { ipc, port } => Value::Str(endpoint(ipc, port, cfg!(windows))),
        }
    }
}

/// The script's `ipc_endpoint`: Windows ZMQ has no `ipc://`, so it falls back to loopback TCP.
pub(crate) fn endpoint(ipc: &str, port: &str, windows: bool) -> String {
    if windows {
        format!("tcp://127.0.0.1:{port}")
    } else {
        format!("ipc://{ipc}")
    }
}

include!(concat!(env!("OUT_DIR"), "/config_table.rs"));

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn endpoints_are_ipc_paths_except_on_windows() {
        assert_eq!(endpoint("/tmp/loki", "8003", false), "ipc:///tmp/loki");
        assert_eq!(endpoint("/tmp/loki", "8003", true), "tcp://127.0.0.1:8003");
    }

    #[test]
    fn leaves_follow_the_script_order_and_naming() {
        let first = &LEAVES[0];
        assert_eq!(first.path, ["logging", "type"]);
        assert_eq!(first.option, "logging-type");
        assert_eq!(first.help, "Type of logger either std_out or file");
    }

    #[test]
    fn optional_leaves_have_their_type() {
        let tags = LEAVES.iter().find(|leaf| leaf.option == "statsd-tags");
        assert!(matches!(
            tags.map(|leaf| &leaf.default),
            Some(DefaultValue::Optional(OptionalKind::List))
        ));
    }
}
